import{_ as a,o as r,c as e,a5 as o}from"./chunks/framework.B5tqjWbr.js";const P=JSON.parse('{"title":"PFC与电机控制集成（PFC-Motor Integration）","description":"","frontmatter":{"date":"2026-06-08T00:00:00.000Z","section":"电机控制","chapter":"pfc-motor-integration","chapterTitle":"PFC 与电机系统","chapterOrder":40,"category":"PFC 与电机系统","source":"motor","visibility":"public","title":"PFC与电机控制集成（PFC-Motor Integration）","tags":["motor-control"],"status":"learning","summary":"**板块概述：** 从功率链路到控制协同，系统掌握PFC与电机控制的联合设计","navGroup":"控制与算法","navGroupOrder":30},"headers":[],"relativePath":"content/motor/pfc-motor-integration/README.md","filePath":"content/motor/pfc-motor-integration/README.md","lastUpdated":1783096495000}'),d={name:"content/motor/pfc-motor-integration/README.md"};function n(h,t,i,s,l,c){return r(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="pfc与电机控制集成-pfc-motor-integration" tabindex="-1">PFC与电机控制集成（PFC-Motor Integration） <a class="header-anchor" href="#pfc与电机控制集成-pfc-motor-integration" aria-label="Permalink to &quot;PFC与电机控制集成（PFC-Motor Integration）&quot;">​</a></h1><p><strong>板块概述：</strong> 从功率链路到控制协同，系统掌握PFC与电机控制的联合设计</p><hr><h2 id="板块概述" tabindex="-1">板块概述 <a class="header-anchor" href="#板块概述" aria-label="Permalink to &quot;板块概述&quot;">​</a></h2><p>本板块聚焦 <strong>PFC（功率因数校正）与电机控制的系统集成问题</strong>——当PFC前级与电机逆变器后级共存于同一功率链路、同一MCU、同一母线电容时，如何实现从AC输入到电机输出的全链路协同设计。</p><p>这不是简单地将PP-04（PFC原理）和ALG-01（FOC理论）拼接，而是要解决两者耦合带来的工程难题：母线电容纹波叠加、控制环带宽冲突、制动能量管理、EMI频谱干扰、保护阈值配合、ADC资源争抢……</p><p><strong>核心认知：</strong> PFC+电机不是&quot;1+1=2&quot;，而是&quot;1+1&gt;2&quot;的系统工程——单独看PFC和电机控制都不难，难的是让它们在同一块PCB上、同一个MCU里和谐共存。</p><hr><h2 id="文档列表" tabindex="-1">文档列表 <a class="header-anchor" href="#文档列表" aria-label="Permalink to &quot;文档列表&quot;">​</a></h2><div class="kb-table-scroll"><table><thead><tr><th>编号</th><th>文档</th><th>难度</th><th>核心内容</th></tr></thead><tbody><tr><td>PMI-01</td><td><a href="./PMI-01-PFC-Motor-System-Architecture.html">PFC与电机控制系统架构</a></td><td></td><td>完整功率链路、PFC拓扑选择、母线电容设计、单芯片集成方案</td></tr><tr><td>PMI-02</td><td><a href="./PMI-02-PFC-Motor-Control-Coordination.html">PFC与电机控制协同</a></td><td></td><td>双环协同控制、制动能量管理、EMI协同设计、保护协调</td></tr><tr><td>PMI-03</td><td><a href="./PMI-03-Appliance-Variable-Frequency.html">家电变频专题</a></td><td></td><td>家电变频架构、压缩机驱动、单芯片PFC+FOC方案、成本优化、认证</td></tr></tbody></table></div><hr><h2 id="与其他板块的交叉关系" tabindex="-1">与其他板块的交叉关系 <a class="header-anchor" href="#与其他板块的交叉关系" aria-label="Permalink to &quot;与其他板块的交叉关系&quot;">​</a></h2><div class="kb-table-scroll"><table><thead><tr><th>关联板块</th><th>关联文档</th><th>关联内容</th></tr></thead><tbody><tr><td>power-path</td><td><a href="./../power-path/PP-04-PFC-Power-Factor-Correction.html">PP-04-PFC-Power-Factor-Correction</a></td><td>PFC原理、Boost PFC控制、THD优化</td></tr><tr><td>power-path</td><td><a href="./../power-path/PP-07-Power-Conversion-Motor-Drive.html">PP-07-Power-Conversion-Motor-Drive</a></td><td>功率变换与电机驱动</td></tr><tr><td>advanced/system-methodology</td><td><a href="./../advanced/system-methodology/SYS-03-PFC-vs-Motor-Control.html">SYS-03-PFC-vs-Motor-Control</a></td><td>PFC与FOC方法论对比、代码架构统一</td></tr><tr><td>algorithm</td><td><a href="./../algorithm/ALG-01-FOC-Theory.html">ALG-01-FOC-Theory</a></td><td>FOC双环控制基础</td></tr><tr><td>algorithm</td><td><a href="./../algorithm/ALG-03-PI-Current-Regulator.html">ALG-03-PI-Current-Regulator</a></td><td>PI参数整定</td></tr><tr><td>advanced/algorithm</td><td><a href="./../advanced/algorithm/ADV-ALG-01-Bandwidth-Filter.html">ADV-ALG-01-Bandwidth-Filter</a></td><td>控制环带宽设计</td></tr><tr><td>hardware</td><td><a href="./../hardware/HW-06-Power-Management-Protection.html">HW-06-Power-Management-Protection</a></td><td>功率管理与保护</td></tr><tr><td>hardware</td><td><a href="./../hardware/HW-07-Thermal-EMC-Design.html">HW-07-Thermal-EMC-Design</a></td><td>热设计与EMC</td></tr></tbody></table></div><hr><h2 id="学习路径建议" tabindex="-1">学习路径建议 <a class="header-anchor" href="#学习路径建议" aria-label="Permalink to &quot;学习路径建议&quot;">​</a></h2><h3 id="路径a-从pfc原理到系统集成-推荐pfc初学者" tabindex="-1">路径A：从PFC原理到系统集成（推荐PFC初学者） <a class="header-anchor" href="#路径a-从pfc原理到系统集成-推荐pfc初学者" aria-label="Permalink to &quot;路径A：从PFC原理到系统集成（推荐PFC初学者）&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PP-04 PFC原理 → SYS-03 PFC vs FOC方法论 → PMI-01 系统架构 → PMI-02 控制协同 → PMI-03 家电专题</span></span></code></pre></div><p><strong>适用人群：</strong> 已掌握FOC，但PFC经验不足的工程师</p><p><strong>预计时间：</strong> 3~4周</p><h3 id="路径b-从家电产品切入-推荐家电开发工程师" tabindex="-1">路径B：从家电产品切入（推荐家电开发工程师） <a class="header-anchor" href="#路径b-从家电产品切入-推荐家电开发工程师" aria-label="Permalink to &quot;路径B：从家电产品切入（推荐家电开发工程师）&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PMI-03 家电变频专题 → PMI-01 系统架构 → PP-04 PFC原理（按需深入）→ PMI-02 控制协同</span></span></code></pre></div><p><strong>适用人群：</strong> 从事空调/冰箱/洗衣机变频开发的工程师</p><p><strong>预计时间：</strong> 2~3周</p><h3 id="路径c-系统架构师快速通览-推荐资深工程师" tabindex="-1">路径C：系统架构师快速通览（推荐资深工程师） <a class="header-anchor" href="#路径c-系统架构师快速通览-推荐资深工程师" aria-label="Permalink to &quot;路径C：系统架构师快速通览（推荐资深工程师）&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>PMI-01 架构概览 → PMI-02 协同设计要点 → 按需深入各专题</span></span></code></pre></div><p><strong>适用人群：</strong> 需要快速掌握PFC+电机集成设计要点的架构师</p><p><strong>预计时间：</strong> 1周</p><hr><h2 id="前置知识要求" tabindex="-1">前置知识要求 <a class="header-anchor" href="#前置知识要求" aria-label="Permalink to &quot;前置知识要求&quot;">​</a></h2><div class="kb-table-scroll"><table><thead><tr><th>知识领域</th><th>最低要求</th><th>推荐掌握</th></tr></thead><tbody><tr><td>FOC控制</td><td>理解双环结构（电流环+速度环）</td><td>ALG-01 + ALG-03 + ALG-05</td></tr><tr><td>PFC基础</td><td>理解Boost PFC工作原理</td><td>PP-04</td></tr><tr><td>电力电子</td><td>理解整流、逆变基本概念</td><td>EE-08</td></tr><tr><td>嵌入式开发</td><td>熟悉STM32/GD32外设配置</td><td>HW-04</td></tr><tr><td>控制理论</td><td>理解PI控制器和带宽概念</td><td>CT-04 + CT-05</td></tr></tbody></table></div>',30)])])}const C=a(d,[["render",n]]);export{P as __pageData,C as default};
